import datetime
start = datetime.date(2021,9,1)
holidays = {datetime.date(2021,9,13), datetime.date(2021,9,14), datetime.date(2021,10,1)}
def workday(n):
    d = start
    count = 0
    while True:
        if d.weekday()<5 and d not in holidays:
            if count==n:
                return d
            count+=1
        d += datetime.timedelta(days=1)
for n in [0,7,8,19,20,31]:
    print(n, workday(n))
EOF
